+        var sysprops = Map.of("cli.name", "", "cli.script", "C:\\foo\\bar\\elasticsearch-mycli.bat", "os.name", "Windows XP");
+        assertThat(getToolName(sysprops), equalTo("mycli"));
+    }
+}
