+
+        TrainedModelAssignmentMetadata.Builder builder = TrainedModelAssignmentMetadata.Builder.fromMetadata(original);
+        assertThat(builder.isChanged(), is(false));
+
+        assertUnchanged(builder, b -> b.removeAssignment(newModel));
